frame.store("_HAMSTRING_STRETCH", __v_480.clone())?;
let __v_481 = Value::from("For the front of the thigh, the quad: stand tall, take one foot behind you and pull the heel up towards your bottom with the knee pointing down at the floor and your hips level, and hold 30 seconds each side - a hand on a wall or a chair for balance. If the pull is at the back of the thigh instead, that is the hamstring: heel on a low step, leg straight, hinge forward from the hips with a flat back, 30 seconds each side. Both after the exercise, when the muscle is warm.");
frame.store("_QUAD_STRETCH", __v_481.clone())?;
